C++ syntax with implementation notes:
```cpp
struct LargeObject {
  int large_array[100000];
  LargeObject() {}
  LargeObject(const LargeObject&) { /* Expensive copy */ }
  LargeObject(LargeObject&&) noexcept { /* Move constructor */ }
};

LargeObject createLargeObject() {
  LargeObject obj; 
  // ... some work with obj ...
  return obj; // Guaranteed copy elision in C++17 and later
}

int main() {
  LargeObject myObj = createLargeObject();
  return 0;
}
```
*Note*: Without RVO/NRVO, `createLargeObject` would create a temporary `LargeObject`, then invoke either the copy constructor (pre-C++11) or the move constructor (C++11 onwards) to initialize `myObj`. This is considerably slower.  With guaranteed elision, the compiler directly constructs `myObj` within `main()`.

code_example:
#include <iostream>
#include <vector>
struct MyObject {
  std::vector<int> data;
  MyObject(const std::vector<int>& d) : data(d) {}
  MyObject() = default;
};
MyObject createObject() {
  std::vector<int> v = {1,2,3,4,5};
  return MyObject(v); // RVO/NRVO candidate
}
int main() {
  auto obj = createObject();
  std::cout << obj.data.size() << std::endl; // Output: 5
  return 0;
}
